{
  "name": "opencode-collaboration",
  "version": "1.2.4",
  "description": "Cross-session messaging for opencode - let independent sessions discover and text each other, modeled after Claude Code's cross-session messaging",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./commands/peers.md": "./commands/peers.md",
    "./commands/list-agents.md": "./commands/list-agents.md",
    "./commands/peers-name.md": "./commands/peers-name.md",
    "./commands/peers-inbox.md": "./commands/peers-inbox.md",
    "./commands/peers-outbox.md": "./commands/peers-outbox.md",
    "./commands/*": "./commands/*"
  },
  "files": [
    "dist",
    "commands",
    "README.md",
    "README.zh-CN.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude-code",
    "cross-session",
    "messaging",
    "multi-agent",
    "ai-coding-agent"
  ],
  "license": "MIT",
  "author": {
    "name": "opencode-collaboration authors"
  },
  "repository": {
    "type": "git",
    "url": "git+https://gitee.com/cqy0/opencode-collaboration.git"
  },
  "bugs": {
    "url": "https://gitee.com/cqy0/opencode-collaboration/issues"
  },
  "homepage": "https://gitee.com/cqy0/opencode-collaboration#readme",
  "engines": {
    "node": ">=18",
    "opencode": ">=1.18.29"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "clean": "node scripts/clean-dist.mjs",
    "build:obfuscated": "npm run clean && tsc -p tsconfig.json && node scripts/obfuscate-dist.mjs",
    "verify:obfuscated": "node scripts/verify-obfuscated.mjs",
    "test": "npm run build:obfuscated && node --test tests/*.test.mjs",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "dry-run": "npm publish --dry-run",
    "prepack": "npm run build:obfuscated && npm run verify:obfuscated",
    "prepublishOnly": "npm run build:obfuscated && npm run verify:obfuscated"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29"
  },
  "dependencies": {
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.29",
    "@opentui/core": "^0.4.5",
    "@opentui/keymap": "^0.4.5",
    "@opentui/solid": "^0.4.5",
    "@types/node": "^22.0.0",
    "javascript-obfuscator": "5.7.0",
    "typescript": "^5.4.0"
  },
  "opencode": {
    "plugin": true,
    "commands": [
      "commands/peers.md",
      "commands/list-agents.md",
      "commands/peers-name.md",
      "commands/peers-inbox.md",
      "commands/peers-outbox.md"
    ]
  }
}
